import type { CSSObject } from '@emotion/react';
import { keyframes } from '@emotion/react';
import emotionStyled from '@emotion/styled';

import { theme } from '../../../theme';
import type { ButtonSize, ButtonVariant } from './Button';

interface StyledButtonProps {
  $css?: CSSObject;
  $elevated: boolean;
  $leading: boolean;
  $size: ButtonSize;
  $trailing: boolean;
  $variant: ButtonVariant;
}

const buttonSizes: Record<ButtonSize, CSSObject> = {
  small: {
    fontSize: theme.fonts.fontSizes['2'],
    height: 32,
    lineHeight: theme.fonts.lineHeights['3'],
    padding: `0 ${theme.spacing['4']}`,
  },
  medium: {
    fontSize: theme.fonts.fontSizes['3'],
    height: 40,
    lineHeight: theme.fonts.lineHeights['6'],
    padding: `0 ${theme.spacing['4']}`,
  },
  large: {
    fontSize: theme.fonts.fontSizes['4'],
    height: 48,
    lineHeight: theme.fonts.lineHeights['6'],
    padding: `0 ${theme.spacing['6']}`,
  },
};

const buttonVariants: Record<ButtonVariant, CSSObject> = {
  primary: {
    backgroundColor: theme.colors.neutral100,
    color: theme.colors.interfaceForegroundLabelPrimary,
    '&:hover:not(:disabled)': {
      color: theme.colors.brandPrimaryBasis,
    },
    '&:active:not(:disabled)': {
      boxShadow: 'none',
      color: theme.colors.interfaceForegroundLabelSecondary,
    },
  },
  secondary: {
    backgroundColor: theme.colors.neutral0,
    border: `1px solid ${theme.colors.neutral100}`,
    color: theme.colors.interfaceLabelPrimary,
    '&:hover:not(:disabled)': {
      backgroundColor: theme.colors.brandPrimaryBasis,
    },
    '&:active:not(:disabled)': {
      boxShadow: 'none',
      color: theme.colors.interfaceLabelDisabled,
    },
  },
  destructive: {
    backgroundColor: theme.colors.semanticErrorText,
    color: theme.colors.interfaceForegroundLabelPrimary,
    '&:hover:not(:disabled)': {
      color: theme.colors.brandPrimaryBasis,
    },
    '&:active:not(:disabled)': {
      boxShadow: 'none',
      color: theme.colors.interfaceForegroundLabelDisabled,
    },
  },
};

const buttonShadows = {
  medium: '0 0.25rem 1rem 0 rgba(0, 0, 0, 0.16)',
  large: '0 0.5rem 1.5rem 0 rgba(0, 0, 0, 0.16)',
};

const iconPadding = (size: ButtonSize, leading: boolean, trailing: boolean) => {
  if (trailing) {
    return size === 'small'
      ? `${theme.spacing['1']} ${theme.spacing['1']} ${theme.spacing['1']} ${theme.spacing['4']}`
      : `${theme.spacing['2']} ${theme.spacing['2']} ${theme.spacing['2']} ${theme.spacing['4']}`;
  }

  if (leading) {
    return size === 'small'
      ? `${theme.spacing['1']} ${theme.spacing['4']} ${theme.spacing['1']} ${theme.spacing['1']}`
      : `${theme.spacing['2']} ${theme.spacing['6']} ${theme.spacing['2']} ${theme.spacing['2']}`;
  }

  return undefined;
};

export const StyledButton = emotionStyled('button', {
  shouldForwardProp: (propName) =>
    ![
      '$css',
      '$elevated',
      '$leading',
      '$size',
      '$trailing',
      '$variant',
    ].includes(propName),
})<StyledButtonProps>(
  ({ $css, $elevated, $leading, $size, $trailing, $variant }) => ({
    alignItems: 'center',
    border: 'none',
    borderRadius: theme.borderRadius.full,
    boxShadow: $elevated ? buttonShadows.medium : 'none',
    boxSizing: 'border-box',
    cursor: 'pointer',
    display: 'flex',
    fontFamily: theme.fonts.paragraph,
    fontWeight: theme.fonts.fontWeights.medium,
    justifyContent: 'center',
    minWidth: 80,
    outline: 'none',
    '& svg': {
      color: theme.colors.neutral100,
    },
    '&:hover': {
      boxShadow: $elevated ? buttonShadows.large : buttonShadows.medium,
    },
    '&:focus-visible': {
      outline: 'auto',
    },
    '&:disabled': {
      background: theme.colors.interfaceSurfacePrimary,
      border: 'none',
      color: theme.colors.interfaceLabelDisabled,
      pointerEvents: 'none',
      '& > div': {
        background: theme.colors.neutral10,
        '& > svg': {
          color: theme.colors.interfaceLabelDisabled,
        },
      },
    },
    ...buttonSizes[$size],
    ...buttonVariants[$variant],
    ...(iconPadding($size, $leading, $trailing)
      ? { padding: iconPadding($size, $leading, $trailing) }
      : {}),
    ...$css,
  }),
);

const colorfulDotPulse = keyframes({
  '0%, 50%, 100%': {
    backgroundColor: theme.colors.brandPrimaryBasis,
  },
  '80%': {
    backgroundColor: theme.colors.interfaceForegroundLabelSecondary,
  },
});

const monoDotPulse = keyframes({
  '0%, 50%, 100%': {
    backgroundColor: theme.colors.interfaceSurfaceSecondary,
  },
  '80%': {
    backgroundColor: theme.colors.interfaceLabelPrimary,
  },
});

export const StyledLoadingIndicator = emotionStyled.div<{
  $colorful: boolean;
}>(({ $colorful }) => ({
  alignItems: 'center',
  display: 'flex',
  justifyContent: 'space-between',
  minWidth: 24,
  width: 24,
  '& > span': {
    animation: `${$colorful ? colorfulDotPulse : monoDotPulse} 0.8s infinite linear both`,
    backgroundColor: theme.colors.neutral0,
    borderRadius: '50%',
    height: 6,
    width: 6,
  },
  '& > span:nth-of-type(1)': {
    animationDelay: '-0.4s',
  },
  '& > span:nth-of-type(2)': {
    animationDelay: '-0.2s',
  },
  '@media (prefers-reduced-motion: reduce)': {
    '& > span': {
      animation: 'none',
    },
  },
}));

const getTrailingMarginLeft = (size: ButtonSize) =>
  size === 'small' ? theme.spacing['2'] : theme.spacing['4'];

const getLeadingMarginRight = (size: ButtonSize) =>
  size === 'large' ? theme.spacing['4'] : theme.spacing['2'];

export const StyledIconContainer = emotionStyled.div<{
  $leading: boolean;
  $size: ButtonSize;
  $trailing: boolean;
}>(({ $leading, $size, $trailing }) => ({
  alignItems: 'center',
  background: theme.colors.brandPrimaryBasis,
  borderRadius: theme.borderRadius.full,
  display: 'flex',
  height: $size === 'large' ? 32 : 24,
  justifyContent: 'center',
  marginLeft: $trailing ? getTrailingMarginLeft($size) : 0,
  marginRight: $leading ? getLeadingMarginRight($size) : 0,
  width: $size === 'large' ? 32 : 24,
}));
